// Keep posts from the last 2 days that actually mention the keyword.
const keyword = $('Your settings').first().json.keyword;
const since = Date.now() - 2 * 24 * 60 * 60 * 1000;

return $input.all().filter(item =>
  (item.json.message || '').toLowerCase().includes(keyword.toLowerCase()) &&
  new Date(item.json.post_created_at).getTime() >= since,
);

// Compares this run with the previous one. Workflow static data keeps the numbers
// between scheduled runs of the active workflow; manual test runs do not save it.
const memory = $getWorkflowStaticData('global');
const settings = $('Your settings').first().json;
const posts = $('Combine posts').first().json.posts.length;
const verdict = $input.first().json.output;
const digest = verdict.digest;
const negativeShare = Math.round(Number(verdict.negative_share) || 0);
const last = memory.lastRun;
const lines = [];

if (last) {
  const volumeChange = last.posts ? Math.round(((posts - last.posts) / last.posts) * 100) : null;
  const sign = n => (n >= 0 ? '+' : '') + n;
  lines.push('Posts: ' + posts + ' (last run ' + last.posts + (volumeChange === null ? '' : ', ' + sign(volumeChange) + '%') +
    '). Negative: ' + negativeShare + '% (last run ' + last.negativeShare + '%).');
  const alerts = [];
  if (volumeChange !== null && volumeChange > 0 && posts >= 5 && volumeChange >= Number(settings.volume_jump_percent)) {
    alerts.push('mentions are up ' + volumeChange + '%');
  }
  const rise = negativeShare - last.negativeShare;
  if (rise > 0 && rise >= Number(settings.negative_jump_points)) {
    alerts.push('negative posts rose from ' + last.negativeShare + '% to ' + negativeShare + '%');
  }
  if (alerts.length) lines.unshift(':warning: *Heads up:* ' + alerts.join(' and ') + '.');
} else {
  lines.push('Posts: ' + posts + '. Negative: ' + negativeShare + '%. The next digest will compare with this one.');
}

memory.lastRun = { posts, negativeShare, at: new Date().toISOString() };
return [{ json: { text: lines.join('\n') + '\n\n' + digest } }];
